// CodeMirror Python hint - nøkkelord + builtins
(function(mod){
  if(typeof exports=="object"&&typeof module=="object")mod(require("../../lib/codemirror"));
  else if(typeof define=="function"&&define.amd)define(["../../lib/codemirror"],mod);
  else mod(CodeMirror);
})(function(CodeMirror){
  "use strict";
  var KW="False None True and as assert async await break class continue def del elif else except finally for from global if import in is lambda nonlocal not or pass raise return try while with yield";
  var BI="abs all any bin bool bytearray bytes callable chr classmethod compile complex delattr dict dir divmod enumerate eval exec filter float format frozenset getattr globals hasattr hash hex id input int isinstance issubclass iter len list locals map max min next object oct open ord pow print property range repr reversed round set setattr slice sorted staticmethod str sum super tuple type vars zip";
  // Ekstra ord: vanlige moduler/funksjoner elevene bruker (math, random, statistics, turtle, matplotlib m.m.)
  var EXTRA="math random statistics datetime time turtle matplotlib pyplot sqrt floor ceil pi factorial randint randrange choice shuffle uniform mean median mode stdev variance sleep forward backward left right penup pendown goto speed color width circle fillcolor begin_fill end_fill done reset clear write shape hideturtle showturtle setheading position getx gety plot scatter bar pie grid show xlabel ylabel title legend Turtle append extend insert remove pop clear index count sort reverse keys values items get update join split strip lower upper replace startswith endswith";
  CodeMirror.registerHelper("hint","python",function(cm){
    var cur=cm.getCursor(),tok=cm.getTokenAt(cur);
    var to=CodeMirror.Pos(cur.line,cur.ch);
    var term,from;
    if(tok.string&&/\w/.test(tok.string[tok.string.length-1])){term=tok.string;from=CodeMirror.Pos(cur.line,tok.start);}
    else{term="";from=to;}
    var found=[],seen={};
    function add(w){if(term&&w.slice(0,term.length)!=term)return;if(w===term)return;if(!seen[w]){seen[w]=true;found.push(w);}}
    (KW+" "+BI+" "+EXTRA).split(" ").forEach(add);
    cm.eachLine(function(line){var m=line.text.match(/\w+/g);if(m)m.forEach(add);});
    if(found.length)return{list:found.sort(),from:from,to:to};
  });
});
